from pathlib import Path
import subprocess,json,base64,hashlib,sys,time
DATA=''
SHA='17974f55b046a98cb7c8374a286db5769d46af700e5abd33ef55092b8444f060'

root=Path('/home/cat/projects/RK3576/rk3576_multimodal_stage5_review');assert not root.is_symlink()
sys.path.insert(0,str(root/'tools'))
from stage5_02_board_run import discover_audio,devices,sample
assert devices(discover_audio())['clear']
report=root/'reports/stage5_03_board/raw_5_2_baseline';report.mkdir()
source=report/'stage5_03_memory_probe.cpp';data=base64.b64decode(DATA);assert hashlib.sha256(data).hexdigest()==SHA
source.write_bytes(data)
cmd=['bash','-c','source "$1/tools/stage5_board_paths.sh"; exec c++ -std=c++17 -O2 -pthread -I"$1/reports/stage5_03_board/baseline_5_2_source/include" "$2/stage5_03_memory_probe.cpp" "$1/build/stage5_02_board/libmultimodal_camera.a" "$1/build/stage5_02_board/libmultimodal_core.a" "$STAGE5_RKLLM_LIB/librkllmrt.so" "$STAGE5_RKNN_LIBRARY" -o "$2/memory_probe"','raw_baseline',str(root),str(report)]
(report/'build.command.json').write_text(json.dumps(cmd,indent=2))
with (report/'build.stdout.log').open('wb') as o,(report/'build.stderr.log').open('wb') as e:r=subprocess.run(cmd,stdout=o,stderr=e,timeout=120)
print('RAW_BUILD',r.returncode,flush=True)
if r.returncode:
 print((report/'build.stderr.log').read_text(),flush=True);raise SystemExit(r.returncode)
cmd=['bash','-c','source "$1/tools/stage5_board_paths.sh"; exec "$2/memory_probe" "$STAGE5_VLM" "$STAGE5_VISION" /dev/video11 "$2" 12','raw_baseline',str(root),str(report)]
(report/'run.command.json').write_text(json.dumps(cmd,indent=2))
with (report/'terminal.log').open('wb') as o,(report/'stderr.log').open('wb') as e,(report/'resources.jsonl').open('w') as mem:
 p=subprocess.Popen(cmd,stdout=o,stderr=e,start_new_session=True);start=time.monotonic()
 while p.poll() is None:
  mem.write(json.dumps(sample(p.pid))+'\n');mem.flush()
  if time.monotonic()-start>180:
   import os,signal
   assert Path(f'/proc/{p.pid}/exe').resolve()==report/'memory_probe'
   os.kill(p.pid,signal.SIGTERM);p.wait(timeout=10);raise RuntimeError('raw baseline timeout; exit failure')
  time.sleep(1)
 result={'build_exit_code':r.returncode,'run_exit_code':p.returncode,'seconds':time.monotonic()-start,'devices_released':devices(discover_audio())['clear'],'production_source_unmodified':True}
(report/'result.json').write_text(json.dumps(result,indent=2));print(json.dumps(result),flush=True)
print((report/'terminal.log').read_text(),flush=True)
print((report/'stderr.log').read_text(),flush=True)
raise SystemExit(p.returncode)
